selector_to_html = {"a[href=\"use-tle-struct.html#loops-and-hints\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Loops and Hints<a class=\"headerlink\" href=\"#loops-and-hints\" title=\"Link to this heading\">#</a></h2><h3>tle.dsa.pipeline\uff0ctle.dsa.parallel\uff0cand tle.dsa.hint<a class=\"headerlink\" href=\"#tle-dsa-pipeline-tle-dsa-parallel-and-tle-dsa-hint\" title=\"Link to this heading\">#</a></h3><p>Loops and Hints API include:</p>", "a[href=\"use-tle-struct.html#execution-orchestration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Execution orchestration<a class=\"headerlink\" href=\"#execution-orchestration\" title=\"Link to this heading\">#</a></h2><h3>tle.gpu.warp_specialize<a class=\"headerlink\" href=\"#tle-gpu-warp-specialize\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.gpu.warp_specialize</span></code> is used to explicitly create a warp-specialized region within the same CTA, placing different JIT functions into different warp partitions. A typical use case is to separate tasks such as TMA/cp.async producers, WGMMA consumers, and epilogue/reduction, and pass shared-memory data between them via <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.pipe</span></code> or other explicit synchronization primitives.</p>", "a[href=\"use-tle-raw.html#integrate-cuda-into-llvm-for-maximum-fine-grained-control\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Integrate CUDA into LLVM for maximum fine-grained control<a class=\"headerlink\" href=\"#integrate-cuda-into-llvm-for-maximum-fine-grained-control\" title=\"Link to this heading\">#</a></h2><p>This section only covers how to integrate CUDA kernel into LLVM inline path. Integrating other vendors into LLVM inline path can follow similar steps.</p><p>TLE-Raw supports CUDA kernel integration via the LLVM inline path. Vendors integrating TLE-Raw on the CUDA side should evaluate:</p>", "a[href=\"use-tle-struct.html#dsa-memory-management-and-data-movement\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">DSA memory management and data movement<a class=\"headerlink\" href=\"#dsa-memory-management-and-data-movement\" title=\"Link to this heading\">#</a></h2><h3>tle.dsa.alloc<a class=\"headerlink\" href=\"#tle-dsa-alloc\" title=\"Link to this heading\">#</a></h3><p>Signature: <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.alloc(shape,</span> <span class=\"pre\">dtype,</span> <span class=\"pre\">mem_addr_space)</span></code>\nPurpose: Allocates a DSA local buffer in the specified memory address space.\nAddress spaces exposed by Huawei Ascend:</p>", "a[href=\"use-tle-lite.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Use TLE-Lite<a class=\"headerlink\" href=\"#use-tle-lite\" title=\"Link to this heading\">#</a></h1><p>This section introduces how to use TLE-Lite. TLE-Lite is available on trition_3.6.x branch.</p>", "a[href=\"use-tle-cpu.html#architecture-overview\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Architecture Overview<a class=\"headerlink\" href=\"#architecture-overview\" title=\"Link to this heading\">#</a></h2>", "a[href=\"use-tle-lite.html#pipeline\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Pipeline<a class=\"headerlink\" href=\"#pipeline\" title=\"Link to this heading\">#</a></h2><h3>Pipe and stage<a class=\"headerlink\" href=\"#pipe-and-stage\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.pipe</span></code> describes an explicit dataflow edge between a producer and one or more consumers. It simultaneously records the shared-memory stage holding the logical chunk and the synchronization required to make that chunk visible to consumers, enabling CTA-level load/compute overlap and warp-specialized producer/consumer code to use a typed descriptor instead of manually writing multiple barriers.</p>", "a[href=\"use-tle-cpu.html#arm64-cpu-related-links\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Arm64 CPU related links<a class=\"headerlink\" href=\"#arm64-cpu-related-links\" title=\"Link to this heading\">#</a></h2><p>Below are the relevant links for TLE-CPU and Arm64:</p>", "a[href=\"use-tle-lite.html#memory-management\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Memory management<a class=\"headerlink\" href=\"#memory-management\" title=\"Link to this heading\">#</a></h2><p>You can use the following operations to manage the memory.</p>", "a[href=\"../FlagTree_overview/FlagTree-overview.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagTree Overview<a class=\"headerlink\" href=\"#flagtree-overview\" title=\"Link to this heading\">#</a></h1><p>FlagTree is an open-source, unified compiler for multiple AI chips. FlagTree is dedicated to building a compiler and associated tooling platform for diverse AI chips, advancing and expanding the upstream and downstream Triton ecosystem, with the goals of supporting existing adaptation solutions, unifying code repositories, and enabling rapid multi-backend support from a single repository. For upstream model users, FlagTree provides unified compilation support across multiple backends; for downstream chip vendors, FlagTree offers reference implementations for integration into the Triton ecosystem.</p>", "a[href=\"use-tle-struct.html#slicing-and-view\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Slicing and view<a class=\"headerlink\" href=\"#slicing-and-view\" title=\"Link to this heading\">#</a></h2><h3>tle.dsa.extract_slice, tle.dsa.insert_slice, tle.dsa.extract_element, and tle.dsa.subview<a class=\"headerlink\" href=\"#tle-dsa-extract-slice-tle-dsa-insert-slice-tle-dsa-extract-element-and-tle-dsa-subview\" title=\"Link to this heading\">#</a></h3><p>Slicing and view API include:</p>", "a[href=\"use-tle-lite.html#distribution\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Distribution<a class=\"headerlink\" href=\"#distribution\" title=\"Link to this heading\">#</a></h2><p>The Triton distributed API consists of four core parts: device mesh definition, sharding specification description, synchronization, and remote access (point-to-point communication).</p><p>Low-level inter-GPU and inter-node communication is provided at different levels: the distributed primitives of TLE-Lite and TLE-Struct perform cross-device communication through FlagCX, whereas TLE-Raw is lower level, sitting at the same level as Raw, and provides device-side communication interfaces directly through NVSHMEM (see <a class=\"reference internal\" href=\"use-tle-raw.html\"><span class=\"std std-doc\">Use TLE-Raw</span></a>); NVSHMEM is used only for NVIDIA GPUs.</p>", "a[href=\"use-tle-lite.html#primitives-interactive-with-local-ptr\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Primitives interactive with local_ptr<a class=\"headerlink\" href=\"#primitives-interactive-with-local-ptr\" title=\"Link to this heading\">#</a></h2><p>The following APIs are used together with <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.gpu.local_ptr</span></code>. For more information, see <a class=\"reference internal\" href=\"use-tle-struct.html\"><span class=\"std std-doc\">Use TLE-Struct</span></a>.</p>", "a[href=\"use-tle-raw.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Use TLE-Raw<a class=\"headerlink\" href=\"#use-tle-raw\" title=\"Link to this heading\">#</a></h1><p>This section introduces how to use TLE-Raw. TLE-Raw is available on trition_3.6.x branch.</p><p>TLE Raw provides a low-level extension interface for Triton, allowing users to fill capability gaps and gain fine-grained control via third-party dialects and languages (for example, using CUDA for thread-level scheduling, synchronization, and memory access). Users can choose between portability and composable optimization (via MLIR dialect integration) and maximum fine-grained control (via CUDA  integration) based on the target hardware and toolchain maturity.</p>", "a[href=\"use-tle-cpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Use TLE-CPU<a class=\"headerlink\" href=\"#use-tle-cpu\" title=\"Link to this heading\">#</a></h1><p>This section introduces how to use TLE-CPU. TLE-CPU is available on trition_3.3.x branch.</p><p>TLE-CPU allows a unified programming paradigm covering diverse edge-side CPU compute power. Extends TLE\u2019s philosophy of \u201clayering hardware deep optimizations on top of <code class=\"docutils literal notranslate\"><span class=\"pre\">@triton.jit</span></code>\u201d to CPUs. Targeting the fragmented CPU ecosystem for edge AI (Arm64 / RISC-V / x86 with multiple coexisting ISAs), it uses the same Triton programming model and integration framework to support diverse ISAs: programming model and correctness are shared across ISAs (plain Triton lands on any ISA via LLVM), while each ISA\u2019s high-performance implementation (intrinsic / C runtime) is contributed separately. Model code is routed to the corresponding ISA implementation through the operator library (FlagGems) vendor dispatch, eliminating the need to be aware of the specific ISA. The differences between CPU and GPU dictate that it requires an independent extension surface:</p>", "a[href=\"use-tle-lite.html#tensor-slicing\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Tensor slicing<a class=\"headerlink\" href=\"#tensor-slicing\" title=\"Link to this heading\">#</a></h2><p>Splits the input tensor into a grid of sub-tiles based on the specified sub-tile shape, and extracts the sub-tile at the given coordinates.\nGPU: Supports extraction into registers and shared memory.</p>", "a[href=\"use-hints.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Use Hints<a class=\"headerlink\" href=\"#use-hints\" title=\"Link to this heading\">#</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree_hints</span></code> allows users to provide optimization hints to the compiler through trailing comments in the Triton Kernel code.</p><p>You can simply add hints by placing a trailing comment with the format <code class=\"docutils literal notranslate\"><span class=\"pre\">#</span> <span class=\"pre\">@hint:</span> <span class=\"pre\">&lt;hint_name&gt;</span></code> on the same line as operations like <code class=\"docutils literal notranslate\"><span class=\"pre\">tl.load</span></code>.</p>", "a[href=\"use-tle-struct.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Use TLE-Struct<a class=\"headerlink\" href=\"#use-tle-struct\" title=\"Link to this heading\">#</a></h1><p>This section introduces how to use TLE-Struct. TLE-Struct is available on trition_3.6.x branch.</p>", "a[href=\"use-tle-struct.html#vector-operators-buffer-form\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Vector operators (Buffer form)<a class=\"headerlink\" href=\"#vector-operators-buffer-form\" title=\"Link to this heading\">#</a></h2><h3>tle.dsa.add, tle.dsa.sub, tle.dsa.mul, tle.dsa.div\uff0ctle.dsa.max\uff0cand tle.dsa.min<a class=\"headerlink\" href=\"#tle-dsa-add-tle-dsa-sub-tle-dsa-mul-tle-dsa-div-tle-dsa-max-and-tle-dsa-min\" title=\"Link to this heading\">#</a></h3><p>Built-in operators:\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.add</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.sub</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.mul</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.div</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.max</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.min</span></code></p><p>General signature:<br/>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.(lhs,</span> <span class=\"pre\">rhs,</span> <span class=\"pre\">out)</span></code></p>", "a[href=\"use-tle-lite.html#scan-and-sort-ops\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Scan and sort Ops<a class=\"headerlink\" href=\"#scan-and-sort-ops\" title=\"Link to this heading\">#</a></h2><p>Scan and sort Ops provide partial tensor primitives such as prefix, rank, and selection, suitable for histogram-based top-k, stream compaction, and block-level sorting and bucketing scenarios.</p><p>TLE-Lite keeps these operations as high-level semantics rather than binding them to a specific hardware implementation: users describe the scan and sort intent, and the backend selects register or shared memory lowering strategies based on the hardware.</p>", "a[href=\"use-tle-struct.html#tle-gpu-barrier-api\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">tle.gpu barrier API<a class=\"headerlink\" href=\"#tle-gpu-barrier-api\" title=\"Link to this heading\">#</a></h2><p>TLE GPU barriers express the synchronization needed by hand-written Hopper producer/consumer pipelines, including TMA completion barriers, empty/full mbarriers, and lightweight named barriers between warp groups.</p><p>API overview:</p>", "a[href=\"use-tle-raw.html#integrate-mlir-dialect-into-llvm-for-portability-and-composable-optimization\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Integrate MLIR dialect into LLVM for portability and composable optimization<a class=\"headerlink\" href=\"#integrate-mlir-dialect-into-llvm-for-portability-and-composable-optimization\" title=\"Link to this heading\">#</a></h2><p>The following is an example of MLIR (Multi-Level Intermediate Representation).</p>", "a[href=\"use-tle-struct.html#gpu-memory-management\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">GPU memory management<a class=\"headerlink\" href=\"#gpu-memory-management\" title=\"Link to this heading\">#</a></h2><p>You can use the following operations to manage the GPU\u2019s memory.</p>", "a[href=\"examples.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Examples<a class=\"headerlink\" href=\"#examples\" title=\"Link to this heading\">#</a></h1><p>This section includes FlagTree examples.</p>", "a[href=\"use-tle-cpu.html#supported-cpu-architectures\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Supported CPU architectures<a class=\"headerlink\" href=\"#supported-cpu-architectures\" title=\"Link to this heading\">#</a></h2>", "a[href=\"examples.html#sparse-mla-forward\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Sparse MLA Forward<a class=\"headerlink\" href=\"#sparse-mla-forward\" title=\"Link to this heading\">#</a></h2><p>This module implements a Triton kernel for the forward pass of a sparse MLA (Multi-Headed Attention) mechanism.\nIt demonstrates the use of <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.load</span></code> for efficient memory access and computation.</p>", "a[href=\"#user-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">User Guide<a class=\"headerlink\" href=\"#user-guide\" title=\"Link to this heading\">#</a></h1><p>This section introduces how to use Hints, TLE-Lite, TLE-Struct, and TLE-Raw compiler languages to optimize the compilation. Regarding how to choose between Hints, TLE-Lite, TLE-Struct, and TLE-Raw, you are recommended to read the <a class=\"reference internal\" href=\"../FlagTree_overview/FlagTree-overview.html\"><span class=\"std std-doc\">FlagTree Overview</span></a> first.</p>", "a[href=\"use-hints.html#supported-hints\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Supported hints<a class=\"headerlink\" href=\"#supported-hints\" title=\"Link to this heading\">#</a></h2><p>The following tables list the optimization hints applicable to Triton operations for compilation on different backends.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
